from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import numpy as np
import pandas as pd

from netnomos.ast import (
    BinaryTerm,
    BoolAnd,
    BoolConst,
    BoolNot,
    BoolOr,
    Compare,
    Constant,
    Exists,
    Formula,
    ForAll,
    FuncCall,
    Implies,
    IndexedRef,
    SymbolRef,
    Term,
    formula_to_string,
)
from netnomos.dataset import PreparedDataset
